    /// The customer's bank, if provided. Can be one of `abn_amro`, `adyen`, `asn_bank`, `bunq`, `buut`, `finom`,
    /// `handelsbanken`, `ing`, `knab`, `mollie`, `moneyou`, `n26`, `nn`, `rabobank`, `regiobank`, `revolut`,
    /// `sns_bank`, `triodos_bank`, `van_lanschot`, or `yoursafe`.
    public var bank: PaymentMethodIdealBank?
    /// The Bank Identifier Code of the customer's bank, if the bank was provided.
    public var bic: PaymentMethodIdealBic?

    enum CodingKeys: String, CodingKey {
        case bank
        case bic
    }

    init() {
        (self.bank, self.bic) = (nil, nil)
    }
}
